const fs=require("fs");
const power=fs.readFileSync("services/WidgetPowerManager.qml","utf8");
const widget=fs.readFileSync("modules/background/widgets/AbstractBackgroundWidget.qml","utf8");

const active='readonly property bool widgetsActive: !root.shouldPauseForOutput("")';
const reduced='readonly property bool reducedMode: !root.widgetsActive';
if(!power.includes(active)||!power.includes(reduced)) process.exit(90);
if(power.indexOf(active)>=power.indexOf(reduced)) process.exit(91);

const pActive='readonly property bool powerActive: WidgetPowerManager.widgetsActiveForOutput(root.outputName)';
const pReduced='readonly property bool powerReduced: !root.powerActive';
if(!widget.includes(pActive)||!widget.includes(pReduced)) process.exit(92);
if(widget.indexOf(pActive)>=widget.indexOf(pReduced)) process.exit(93);

if(!power.includes("function _triggersForOutputWithEligibility(outputName: string, outputAllowed: bool): var")) process.exit(94);
if(!power.includes("outputAllowed = DesktopWidgetLayout.outputAllowed(scopedOutput);")) process.exit(95);
if(!power.includes("const triggers = root._triggersForOutputWithEligibility(outputName, outputAllowed);")) process.exit(96);

function oldDecision(c,t){
  const scoped=String(c.outputName??""); t.push("normalize:outer");
  if(scoped.length>0){
    t.push("allowed:first");
    if(!c.allowed) return true;
  }
  t.push("enabled");
  if(!c.enabled){ return false; }
  t.push("edit:early");
  if(c.edit) return false;

  t.push("normalize:trigger");
  let outputDisabled=false;
  if(scoped.length>0){
    t.push("allowed:trigger");
    outputDisabled=!c.allowed;
  }
  t.push("pauseGame");
  const game=c.pauseGame ? (t.push("game"),c.game) : false;
  t.push("pauseFullscreen");
  const fullscreen=c.pauseFullscreen ? (t.push("fullscreen"),c.fullscreen) : false;
  t.push("pauseWindows");
  const windows=c.pauseWindows ? (t.push("windows"),c.windows) : false;
  t.push("edit:trigger");
  return outputDisabled||game||fullscreen||windows;
}
function newDecision(c,t){
  const scoped=String(c.outputName??""); t.push("normalize:outer");
  let allowed=true;
  if(scoped.length>0){
    t.push("allowed:first");
    allowed=c.allowed;
    if(!allowed) return true;
  }
  t.push("enabled");
  if(!c.enabled) return false;
  t.push("edit:early");
  if(c.edit) return false;

  t.push("normalize:trigger");
  const outputDisabled=scoped.length>0&&!allowed;
  t.push("pauseGame");
  const game=c.pauseGame ? (t.push("game"),c.game) : false;
  t.push("pauseFullscreen");
  const fullscreen=c.pauseFullscreen ? (t.push("fullscreen"),c.fullscreen) : false;
  t.push("pauseWindows");
  const windows=c.pauseWindows ? (t.push("windows"),c.windows) : false;
  t.push("edit:trigger");
  return outputDisabled||game||fullscreen||windows;
}
function withoutSecondAllowed(trace){return trace.filter(x=>x!=="allowed:trigger");}
for(const outputName of ["","DP-1"]){
 for(const allowed of [false,true])
 for(const enabled of [false,true])
 for(const edit of [false,true])
 for(const pauseGame of [false,true])
 for(const game of [false,true])
 for(const pauseFullscreen of [false,true])
 for(const fullscreen of [false,true])
 for(const pauseWindows of [false,true])
 for(const windows of [false,true]){
   const c={outputName,allowed,enabled,edit,pauseGame,game,pauseFullscreen,fullscreen,pauseWindows,windows};
   const a=[],b=[];
   const av=oldDecision(c,a),bv=newDecision(c,b);
   if(av!==bv) process.exit(10);
   if(JSON.stringify(withoutSecondAllowed(a))!==JSON.stringify(b)) process.exit(11);
   const expectedRemoved=(outputName!==""&&allowed&&enabled&&!edit)?1:0;
   const removed=a.filter(x=>x==="allowed:trigger").length;
   if(removed!==expectedRemoved) process.exit(12);
 }
}

// Public inverse contracts: one decision produces both values, exactly complementary.
for(const paused of [false,true]){
 const oldGlobal={widgetsActive:!paused,reducedMode:paused};
 const newGlobal={widgetsActive:!paused,reducedMode:!(!paused)};
 if(JSON.stringify(oldGlobal)!==JSON.stringify(newGlobal)) process.exit(20);
 const oldWidget={powerActive:!paused,powerReduced:paused};
 const newWidget={powerActive:!paused,powerReduced:!(!paused)};
 if(JSON.stringify(oldWidget)!==JSON.stringify(newWidget)) process.exit(21);
}
process.exit(0);
